const AI_CAPSTONES: Record<string, UnitContent> = {
  python_for_ai: pythonSupportParser,
  agentic_systems: agentSupportFlow,
  llmops: llmReleaseGate,
  ai_security: aiThreatReview,
  ai_product: productHandoff,
  ai_development: aiPatchEvidence,
};

export function expandAiStackCapstones(course: CourseContent): CourseContent {
  const practicalUnit = AI_CAPSTONES[course.slug];
  return practicalUnit ? expandCourse(course, {}, [practicalUnit]) : course;
}
